$if macos {
	#flag -framework Foundation
	#include <objc/runtime.h>
}
#include <dlfcn.h>
fn C.objc_getClass(&char) voidptr
fn C.sel_registerName(&char) voidptr
fn C.dlsym(voidptr, &char) voidptr
fn C.class_getInstanceSize(voidptr) usize
fn C.class_getSuperclass(voidptr) voidptr
fn C.class_getClassMethod(voidptr, voidptr) voidptr
fn C.method_getTypeEncoding(voidptr) &char
fn C.objc_storeWeak(&u64, voidptr) voidptr

type KeyedUnarchiveSend = fn (u64, u64, u64, u64, u64, u64) u64
type KeyedUnarchiveRealSend = fn (u64, u64, f64) u64
struct KeyedUnarchiveApi { native bool send u64 }
fn (api KeyedUnarchiveApi) cls(name string) u64 {
	$if macos { if api.native { return u64(C.objc_getClass(name.str)) } }
	return ios_runtime.names[name]
}
fn (api KeyedUnarchiveApi) selector(name &char) u64 {
	$if macos { if api.native { return u64(C.sel_registerName(name)) } }
	return u64(name)
}
fn (api KeyedUnarchiveApi) message(object u64, name &char, a u64, b u64, c u64, d u64) u64 {
	return unsafe { KeyedUnarchiveSend(voidptr(api.send))(object, api.selector(name), a, b, c, d) }
}
fn (api KeyedUnarchiveApi) real(object u64, name &char, value f64) u64 {
	if !api.native && object == api.cls('NSNumber') {
		number := objc_allocate(object); mut header := obj_header(number)
		header.is_real = true; header.real_number = value
		return objc_autorelease(number)
	}
	return unsafe { KeyedUnarchiveRealSend(voidptr(api.send))(object, api.selector(name), value) }
}
fn (api KeyedUnarchiveApi) number(word u64, unsigned bool, boolean bool) u64 {
	if !api.native {
		number := objc_allocate(api.cls('NSNumber')); mut header := obj_header(number)
		header.number = i64(word); header.unsigned_number = unsigned; header.cf_boolean = boolean
		return objc_autorelease(number)
	}
	return api.message(api.cls('NSNumber'), if boolean { c'numberWithBool:' } else if unsigned { c'numberWithUnsignedLongLong:' } else { c'numberWithLongLong:' }, word, 0, 0, 0)
}
fn (api KeyedUnarchiveApi) string(text string) u64 { return api.message(api.cls('NSString'), c'stringWithUTF8String:', u64(text.str), 0, 0, 0) }
fn (api KeyedUnarchiveApi) pool() u64 {
	$if macos { if api.native { return api.message(api.cls('NSAutoreleasePool'), c'new', 0, 0, 0, 0) } }
	return objc_pool_push()
}
fn (api KeyedUnarchiveApi) drain(pool u64) {
	$if macos { if api.native { api.message(pool, c'drain', 0, 0, 0, 0); return } }
	objc_pool_pop(pool)
}
fn (api KeyedUnarchiveApi) weak(slot &u64, object u64) {
	$if macos { if api.native { C.objc_storeWeak(slot, unsafe { voidptr(object) }); return } }
	objc_store_weak(slot, object)
}
fn (api KeyedUnarchiveApi) destroy_weak(slot &u64) {
	$if macos { if api.native { C.objc_storeWeak(slot, unsafe { nil }); return } }
	objc_destroy_weak(slot)
}
fn (api KeyedUnarchiveApi) bytes(data u64) []u8 {
	length := api.message(data, c'length', 0, 0, 0, 0)
	pointer := api.message(data, c'bytes', 0, 0, 0, 0)
	return if length == 0 { []u8{} } else { unsafe { (&u8(voidptr(pointer))).vbytes(int(length)).clone() } }
}
fn (api KeyedUnarchiveApi) array(values []u64, mutable bool) u64 {
	return api.message(api.cls(if mutable { 'NSMutableArray' } else { 'NSArray' }), c'arrayWithObjects:count:', u64(values.data), u64(values.len), 0, 0)
}
fn (api KeyedUnarchiveApi) dictionary(keys []u64, values []u64, mutable bool) u64 {
	return api.message(api.cls(if mutable { 'NSMutableDictionary' } else { 'NSDictionary' }), c'dictionaryWithObjects:forKeys:count:', u64(values.data), u64(keys.data), u64(keys.len), 0)
}
fn (api KeyedUnarchiveApi) corpus(name string) u64 {
	numbers := api.cls('NSNumber')
	match name {
		'nil' { return 0 }
		'nul-string' {
			bytes := [u8(97), 0, 98]!
			if !api.native { return objc_autorelease(owned_string(unsafe { tos(&bytes[0], bytes.len) })) }
			value := api.message(api.message(api.cls('NSString'), c'alloc', 0, 0, 0, 0), c'initWithBytes:length:encoding:', u64(unsafe { &bytes[0] }), u64(bytes.len), 4, 0)
			return api.message(value, c'autorelease', 0, 0, 0, 0)
		}
		'string', 'empty-string', 'long-string' { return api.string(if name == 'empty-string' { '' } else if name == 'long-string' { 'ascii'.repeat(300) } else { 'keyed & < 😀 é' }) }
		'mutable-string' {
			value := api.message(api.message(api.cls('NSMutableString'), c'alloc', 0, 0, 0, 0), c'initWithString:', api.string('keyed & < 😀 é'), 0, 0, 0)
			return api.message(value, c'autorelease', 0, 0, 0, 0)
		}
		'false', 'true' { return api.number(u64(name == 'true'), false, true) }
		'zero', 'negative', 'minimum', 'positive', 'unsigned-high', 'unsigned-max' {
			word := match name { 'negative' { u64(i64(-43)) } 'minimum', 'unsigned-high' { u64(1) << 63 } 'positive' { u64(0x123456789) } 'unsigned-max' { ~u64(0) } else { u64(0) } }
			return api.number(word, name.starts_with('unsigned'), false)
		}
		'real', 'negative-zero', 'infinity', 'nan' {
			word := match name { 'negative-zero' { u64(1) << 63 } 'infinity' { u64(0x7ff0000000000000) } 'nan' { u64(0x7ff8000000000000) } else { u64(0x3ff4000000000000) } }
			return api.real(numbers, c'numberWithDouble:', bits.f64_from_bits(word))
		}
		'data', 'empty-data', 'mutable-data', 'large-data' {
			mut bytes := []u8{len: if name == 'empty-data' { 0 } else if name == 'large-data' { 70000 } else { 4 }}
			for i in 0 .. bytes.len { bytes[i] = u8(i * 73 + 17) }
			if !api.native && name == 'mutable-data' {
				data := objc_allocate(api.cls('NSMutableData'))
				obj_header(data).data = bytes.clone()
				return objc_autorelease(data)
			}
			return api.message(api.cls(if name == 'mutable-data' { 'NSMutableData' } else { 'NSData' }), c'dataWithBytes:length:', u64(bytes.data), u64(bytes.len), 0, 0)
		}
		'date' { return api.real(api.cls('NSDate'), c'dateWithTimeIntervalSinceReferenceDate:', -12345.25) }
		'null' { return api.message(api.cls('NSNull'), c'null', 0, 0, 0, 0) }
		'array', 'mutable-array' {
			child := api.string('shared child')
			return api.array([child, api.corpus('negative'), child, api.corpus('null')], name == 'mutable-array')
		}
		'empty-array' { return api.array([]u64{}, false) }
		'dictionary', 'mutable-dictionary' { return api.dictionary([api.string('text'), api.string('array')], [api.string('value'), api.corpus('array')], name == 'mutable-dictionary') }
		'empty-dictionary' { return api.dictionary([]u64{}, []u64{}, false) }
		'distinct-equal' { return api.array([api.corpus('mutable-string'), api.corpus('mutable-string')], false) }
		'wide-references' {
			mut values := []u64{cap: 300}
			for i in 0 .. 300 { values << api.string('distinct-' + i.str()) }
			return api.array(values, false)
		}
		'depth-boundary' { mut root := api.string('leaf'); for _ in 0 .. 64 { root = api.array([root], false) }; return root }
		else { panic('unknown keyed archive corpus ' + name) }
	}
}

type KeyedUnarchiveGetReal = fn (u64, u64) f64
fn (api KeyedUnarchiveApi) get_real(object u64, selector &char) f64 {
	$if macos { if api.native { return unsafe { KeyedUnarchiveGetReal(voidptr(api.send))(object, api.selector(selector)) } } }
	mut frame := RegisterFrame{}
	frame.x[0] = object; frame.x[1] = u64(selector)
	assert objc_dispatch(mut frame, 0) == 0
	return frame_double(frame, 0)
}
fn (api KeyedUnarchiveApi) text(object u64) string {
	$if macos {
		if api.native {
			length := api.message(object, c'lengthOfBytesUsingEncoding:', 4, 0, 0, 0)
			pointer := api.message(object, c'UTF8String', 0, 0, 0, 0)
			return if length == 0 { '' } else { unsafe { tos(&u8(voidptr(pointer)), int(length)).clone() } }
		}
	}
	return string_text(object).clone()
}
fn (api KeyedUnarchiveApi) data(bytes []u8) u64 { return api.message(api.cls('NSData'), c'dataWithBytes:length:', u64(bytes.data), u64(bytes.len), 0, 0) }
fn (api KeyedUnarchiveApi) allowed(names []string) u64 {
	mut classes := []u64{cap: names.len}
	for name in names { classes << api.cls(name) }
	defer { unsafe { classes.free() } }
	return api.message(api.cls('NSSet'), c'setWithObjects:count:', u64(classes.data), u64(classes.len), 0, 0)
}
fn keyed_unarchive_names() [33]string {
	return ['nil', 'string', 'nul-string', 'empty-string', 'long-string', 'mutable-string', 'false', 'true', 'zero', 'negative', 'minimum', 'positive', 'unsigned-high', 'unsigned-max', 'real', 'negative-zero', 'infinity', 'nan', 'data', 'empty-data', 'mutable-data', 'large-data', 'date', 'null', 'array', 'mutable-array', 'empty-array', 'dictionary', 'mutable-dictionary', 'empty-dictionary', 'distinct-equal', 'wide-references', 'depth-boundary']!
}
fn (api KeyedUnarchiveApi) native_data(name string) u64 {
	bytes := keyed_unarchive_native_bytes(name)
	defer { unsafe { bytes.free() } }
	return api.data(bytes)
}
fn (api KeyedUnarchiveApi) decode(data u64, mode int, error_slot &u64) u64 {
	return match mode {
		0 { api.message(api.cls('NSKeyedUnarchiver'), c'unarchiveObjectWithData:', data, 0, 0, 0) }
		1 { api.message(api.cls('NSKeyedUnarchiver'), c'unarchiveTopLevelObjectWithData:error:', data, u64(error_slot), 0, 0) }
		2 { api.message(api.cls('NSKeyedUnarchiver'), c'unarchivedObjectOfClass:fromData:error:', api.cls('NSObject'), data, u64(error_slot), 0) }
		else { api.message(api.cls('NSKeyedUnarchiver'), c'unarchivedObjectOfClasses:fromData:error:', api.allowed(['NSString', 'NSNumber', 'NSData', 'NSDate', 'NSNull', 'NSArray', 'NSDictionary']), data, u64(error_slot), 0) }
	}
}
fn (api KeyedUnarchiveApi) validate(object u64, name string) {
	if name == 'nil' { assert object == 0; return }
	assert object != 0, name
	class_name := match name {
		'false', 'true', 'zero', 'negative', 'minimum', 'positive', 'unsigned-high', 'unsigned-max', 'real', 'negative-zero', 'infinity', 'nan' { 'NSNumber' }
		'data', 'empty-data', 'large-data' { 'NSData' }
		'mutable-data' { 'NSMutableData' }
		'array', 'empty-array', 'distinct-equal', 'wide-references', 'depth-boundary' { 'NSArray' }
		'mutable-array' { 'NSMutableArray' }
		'dictionary', 'empty-dictionary' { 'NSDictionary' }
		'mutable-dictionary' { 'NSMutableDictionary' }
		'mutable-string' { 'NSMutableString' }
		'date' { 'NSDate' }
		'null' { 'NSNull' }
		else { 'NSString' }
	}
	assert api.message(object, c'isKindOfClass:', api.cls(class_name), 0, 0, 0) == 1, name
	match name {
		'string', 'empty-string', 'long-string', 'mutable-string', 'nul-string' {
			expected := if name == 'empty-string' { '' } else if name == 'long-string' { 'ascii'.repeat(300) } else if name == 'nul-string' { 'a\x00b' } else { 'keyed & < 😀 é' }
			assert api.text(object) == expected, name
		}
		'false', 'true', 'zero', 'negative', 'minimum', 'positive', 'unsigned-high', 'unsigned-max' {
			expected := match name { 'true' { u64(1) } 'negative' { u64(i64(-43)) } 'minimum', 'unsigned-high' { u64(1) << 63 } 'positive' { u64(0x123456789) } 'unsigned-max' { ~u64(0) } else { u64(0) } }
			assert api.message(object, c'unsignedIntegerValue', 0, 0, 0, 0) == expected, name
			if !api.native {
				header := obj_header(object)
				assert header.cf_boolean == (name in ['false', 'true']), name
				assert !header.is_real
				if name.starts_with('unsigned') { assert header.unsigned_number }
			}
		}
		'real', 'negative-zero', 'infinity', 'nan' {
			expected := match name { 'negative-zero' { u64(1) << 63 } 'infinity' { u64(0x7ff0000000000000) } 'nan' { u64(0x7ff8000000000000) } else { u64(0x3ff4000000000000) } }
			assert bits.f64_bits(api.get_real(object, c'doubleValue')) == expected, name
		}
		'data', 'empty-data', 'mutable-data', 'large-data' {
			bytes := api.bytes(object)
			assert bytes.len == if name == 'empty-data' { 0 } else if name == 'large-data' { 70000 } else { 4 }
			for i, byte in bytes { assert byte == u8(i * 73 + 17) }
			unsafe { bytes.free() }
		}
		'date' { assert bits.f64_bits(api.get_real(object, c'timeIntervalSinceReferenceDate')) == bits.f64_bits(-12345.25) }
		'null' {}
		'array', 'mutable-array', 'empty-array', 'distinct-equal', 'wide-references' {
			count := api.message(object, c'count', 0, 0, 0, 0)
			if name == 'empty-array' { assert count == 0 }
			else if name == 'distinct-equal' {
				assert count == 2
				first := api.message(object, c'objectAtIndex:', 0, 0, 0, 0); second := api.message(object, c'objectAtIndex:', 1, 0, 0, 0)
				assert first != second; api.validate(first, 'mutable-string'); api.validate(second, 'mutable-string')
			} else if name == 'wide-references' {
				assert count == 300
				for i in 0 .. 300 { assert api.text(api.message(object, c'objectAtIndex:', u64(i), 0, 0, 0)) == 'distinct-' + i.str() }
			} else {
				assert count == 4
				assert api.message(object, c'objectAtIndex:', 0, 0, 0, 0) == api.message(object, c'objectAtIndex:', 2, 0, 0, 0)
				assert api.text(api.message(object, c'objectAtIndex:', 0, 0, 0, 0)) == 'shared child'
				api.validate(api.message(object, c'objectAtIndex:', 1, 0, 0, 0), 'negative')
				api.validate(api.message(object, c'objectAtIndex:', 3, 0, 0, 0), 'null')
			}
		}
		'dictionary', 'mutable-dictionary', 'empty-dictionary' {
			assert api.message(object, c'count', 0, 0, 0, 0) == if name == 'empty-dictionary' { 0 } else { 2 }
			if name != 'empty-dictionary' {
				assert api.text(api.message(object, c'objectForKey:', api.string('text'), 0, 0, 0)) == 'value'
				api.validate(api.message(object, c'objectForKey:', api.string('array'), 0, 0, 0), 'array')
			}
		}
		'depth-boundary' {
			mut nested := object
			for _ in 0 .. 64 { assert api.message(nested, c'count', 0, 0, 0, 0) == 1; nested = api.message(nested, c'objectAtIndex:', 0, 0, 0, 0) }
			assert api.text(nested) == 'leaf'
		}
		else { panic('unvalidated decoded case ' + name) }
	}
}
fn keyed_unarchiver_native_api() KeyedUnarchiveApi {
	$if macos { return KeyedUnarchiveApi{native: true, send: u64(C.dlsym(unsafe { voidptr(-2) }, c'objc_msgSend'))} }
	return KeyedUnarchiveApi{}
}
fn keyed_unarchiver_shared(api KeyedUnarchiveApi) {
	for name in keyed_unarchive_names() {
		for source in 0 .. 2 {
			for mode in 0 .. 4 {
				pool := api.pool()
				data := if source == 0 { api.native_data(name) } else { api.message(api.cls('NSKeyedArchiver'), c'archivedDataWithRootObject:', api.corpus(name), 0, 0, 0) }
				mut errors := [u64(0x1122334455667788), 0x5a5a5a5a5a5a5a5a, 0x8877665544332211]!
				object := api.decode(data, mode, unsafe { &errors[1] })
				assert errors[0] == 0x1122334455667788 && errors[2] == 0x8877665544332211
				if name == 'nil' && mode != 0 { api.error(errors[1], 4865) }
				else { assert errors[1] == 0x5a5a5a5a5a5a5a5a, name }
				api.validate(object, name)
				api.drain(pool)
			}
		}
	}
	// A retained result owns its decoded graph independently of the input NSData.
	pool := api.pool()
	data := api.native_data('mutable-string')
	mut data_weak := u64(0); mut object_weak := u64(0)
	api.weak(unsafe { &data_weak }, data)
	mut error_slot := u64(0)
	object := api.decode(data, 1, unsafe { &error_slot }); assert error_slot == 0
	api.message(object, c'retain', 0, 0, 0, 0); api.weak(unsafe { &object_weak }, object)
	api.drain(pool); assert data_weak == 0 && object_weak != 0
	after := api.pool(); api.validate(object, 'mutable-string')
	api.message(object, c'setString:', api.string('decoded mutation'), 0, 0, 0)
	assert api.text(object) == 'decoded mutation'
	api.message(object, c'release', 0, 0, 0, 0); api.drain(after)
	assert object_weak == 0
	api.destroy_weak(unsafe { &data_weak }); api.destroy_weak(unsafe { &object_weak })
}
fn (api KeyedUnarchiveApi) error(error_object u64, code u64) {
	assert error_object != 0 && error_object != 0x5a5a5a5a5a5a5a5a
	assert api.message(error_object, c'code', 0, 0, 0, 0) == code
	assert api.text(api.message(error_object, c'domain', 0, 0, 0, 0)) == 'NSCocoaErrorDomain'
}

fn keyed_unarchiver_shared_errors(api KeyedUnarchiveApi) {
	// Foundation's secure API checks archive records, not primitive plist values.
	for name in ['string', 'false', 'negative', 'real', 'data']! {
		pool := api.pool(); data := api.native_data(name)
		for allow in [api.allowed(['NSArray']), api.allowed([]string{}), u64(0)]! {
			mut error_slot := u64(0x5a5a5a5a5a5a5a5a)
			object := api.message(api.cls('NSKeyedUnarchiver'), c'unarchivedObjectOfClasses:fromData:error:', allow, data, u64(unsafe { &error_slot }), 0)
			api.validate(object, name); assert error_slot == 0x5a5a5a5a5a5a5a5a
		}
		api.drain(pool)
	}
	for name in ['mutable-string', 'mutable-data', 'date', 'null', 'array', 'dictionary']! {
		pool := api.pool(); data := api.native_data(name)
		mut error_slot := u64(0)
		object := api.message(api.cls('NSKeyedUnarchiver'), c'unarchivedObjectOfClass:fromData:error:', api.cls('NSNumber'), data, u64(unsafe { &error_slot }), 0)
		assert object == 0; api.error(error_slot, 4864)
		assert api.message(api.cls('NSKeyedUnarchiver'), c'unarchivedObjectOfClass:fromData:error:', api.cls('NSNumber'), data, 0, 0) == 0
		api.drain(pool)
	}
	for pair in [['mutable-string', 'NSString']!, ['mutable-data', 'NSData']!, ['depth-boundary', 'NSArray']!]! {
		pool := api.pool(); mut error_slot := u64(0)
		object := api.message(api.cls('NSKeyedUnarchiver'), c'unarchivedObjectOfClass:fromData:error:', api.cls(pair[1]), api.native_data(pair[0]), u64(unsafe { &error_slot }), 0)
		api.validate(object, pair[0]); assert error_slot == 0; api.drain(pool)
	}
	for malformed in ['nil', 'empty', 'junk', 'truncated']! {
		pool := api.pool()
		mut bytes := if malformed == 'truncated' { keyed_unarchive_native_bytes('string') } else if malformed == 'junk' { 'not a property list'.bytes() } else { []u8{} }
		if malformed == 'truncated' { bytes.trim(bytes.len - 1) }
		data := if malformed == 'nil' { u64(0) } else { api.data(bytes) }
		for mode in 0 .. 4 {
			mut errors := [u64(0x1122334455667788), 0x5a5a5a5a5a5a5a5a, 0x8877665544332211]!
			assert api.decode(data, mode, unsafe { &errors[1] }) == 0
			assert errors[0] == 0x1122334455667788 && errors[2] == 0x8877665544332211
			if mode == 0 { assert errors[1] == 0x5a5a5a5a5a5a5a5a }
			else if mode == 1 { assert errors[1] == 0 }
			else { api.error(errors[1], 4864) }
		}
		unsafe { bytes.free() }; api.drain(pool)
	}
}

fn keyed_unarchiver_shared_key_copy(api KeyedUnarchiveApi) {
	pool := api.pool(); bytes := keyed_unarchive_mutable_key_bytes(); mut error_slot := u64(0)
	dictionary := api.decode(api.data(bytes), 3, unsafe { &error_slot })
	assert error_slot == 0 && api.message(dictionary, c'count', 0, 0, 0, 0) == 1
	mut state := [8]u64{}
	mut buffer := [u64(0), 0xcafe]!
	assert api.message(dictionary, c'countByEnumeratingWithState:objects:count:', u64(unsafe { &state[0] }), u64(unsafe { &buffer[0] }), 1, 0) == 1
	assert state[1] != 0 && state[2] != 0 && buffer[1] == 0xcafe
	key := unsafe { *(&u64(voidptr(state[1]))) }
	value := api.message(dictionary, c'objectForKey:', key, 0, 0, 0)
	assert key != value && api.text(key) == 'mutable-key' && api.text(value) == 'mutable-key'
	api.message(value, c'appendString:', api.string('-changed'), 0, 0, 0)
	assert api.text(key) == 'mutable-key' && api.text(value) == 'mutable-key-changed'
	assert api.message(dictionary, c'objectForKey:', api.string('mutable-key'), 0, 0, 0) == value
	unsafe { bytes.free() }; api.drain(pool)
}
fn test_keyed_unarchiver_native() {
	$if macos {
		api := keyed_unarchiver_native_api()
		assert C.class_getInstanceSize(unsafe { voidptr(api.cls('NSKeyedUnarchiver')) }) == 144
		assert C.class_getSuperclass(unsafe { voidptr(api.cls('NSKeyedUnarchiver')) }) == unsafe { voidptr(api.cls('NSCoder')) }
		for name, expected in {'unarchiveObjectWithData:': '@24@0:8@16', 'unarchiveTopLevelObjectWithData:error:': '@32@0:8@16^@24', 'unarchivedObjectOfClass:fromData:error:': '@40@0:8#16@24^@32', 'unarchivedObjectOfClasses:fromData:error:': '@40@0:8@16@24^@32'} {
			method := C.class_getClassMethod(unsafe { voidptr(api.cls('NSKeyedUnarchiver')) }, C.sel_registerName(name.str))
			assert method != unsafe { nil } && unsafe { C.method_getTypeEncoding(method).vstring() } == expected
		}
		keyed_unarchiver_shared(api); keyed_unarchiver_shared_errors(api); keyed_unarchiver_shared_key_copy(api)
		println('IOS-KEYED-UNARCHIVER-NATIVE:264 builtin graph/source/factory cases, scalar bits, UID identity, mutability, depth64, input/result lifetime, allowlist inheritance, primitive bypass and measured nil/malformed errors')
	}
}


// Captured native Foundation binary archives; generated by the sealed V probe.
fn keyed_unarchive_native_bytes(name string) []u8 {
 match name {
