fn keyed_unarchive_mutable_key_bytes() []u8 { return hex.decode('') or { panic(err) } }

// Runtime-only fixtures.
__global keyed_unarchiver_callback_input = u64(0)
__global keyed_unarchiver_callback_fired = false
__global keyed_unarchiver_number_fail = false
__global keyed_unarchiver_null_fail = false
fn keyed_unarchiver_runtime_api() KeyedUnarchiveApi { return KeyedUnarchiveApi{send: u64(unsafe { voidptr(C.ios_objc_builtin) })} }
fn keyed_unarchiver_drop_input() {
	pool := objc_pool_push()
	assert data_length(keyed_unarchiver_callback_input) > 40
	assert unsafe { *(&u8(voidptr(data_pointer(keyed_unarchiver_callback_input)))) } == `b`
	other := objc_new(ios_runtime.names['NSObject']); objc_release(other)
	objc_release(keyed_unarchiver_callback_input); objc_pool_pop(pool)
}
fn keyed_unarchiver_string_constructor(object u64, selector &char) u64 {
	if keyed_unarchiver_callback_input != 0 && !keyed_unarchiver_callback_fired {
		keyed_unarchiver_callback_fired = true
		worker := spawn keyed_unarchiver_drop_input(); worker.wait()
	}
	return object
}
fn keyed_unarchiver_number_constructor(object u64, selector &char) u64 { return if keyed_unarchiver_number_fail { u64(0) } else { object } }
fn keyed_unarchiver_null_constructor(object u64, selector &char) u64 {
	if keyed_unarchiver_null_fail { return 0 }
	return keyed_unarchiver_string_constructor(object, selector)
}
fn keyed_unarchiver_only_cached_null() {
	object := ios_runtime.null_object
	assert object != 0 && ios_runtime.live == 1 && ios_runtime.objects.len == 1
	assert object in ios_runtime.objects && ios_runtime.framework_objects == [object]
	assert read64(object) == ios_runtime.names['NSNull'] && obj_header(object).refs == 1
	assert ios_runtime.weak.len == 0
}
fn keyed_unarchiver_forbidden_coding(object u64, selector &char, coder u64) u64 { C._exit(19); return 0 }
fn test_keyed_unarchiver_runtime() {
	for _ in 0 .. 2 {
		objc_start(); system_data_start()!; api := keyed_unarchiver_runtime_api()
		cls := api.cls('NSKeyedUnarchiver'); library := '/System/Library/Frameworks/Foundation.framework/Foundation'
		assert runtime_symbol(library, '_OBJC_CLASS_$_NSKeyedUnarchiver')! == cls
		assert runtime_symbol(library, '_OBJC_METACLASS_$_NSKeyedUnarchiver')! == read64(cls)
		assert objc_class_size(cls) == 144 && objc_class_parent(cls) == api.cls('NSCoder')
		assert ios_runtime.classes[cls].ivars.len == 17
		for i, pair in [['_delegate', '@"<NSKeyedUnarchiverDelegate>"']!, ['_flags', 'AQ']!, ['_objRefMap', '^{__CFDictionary=}']!, ['_replacementMap', '^{__CFDictionary=}']!, ['_nameClassMap', '^{__CFDictionary=}']!, ['_tmpRefObjMap', '^{__CFDictionary=}']!, ['_refObjMap', '^{__CFDictionary=}']!, ['_genericKey', 'i']!, ['_offsetData', '^{?={?=[5C]CCCQQQ}QQ}']!, ['_containers', '^{__CFArray=}']!, ['_objects', '^{__CFArray=}']!, ['_data', '^{__CFData=}']!, ['_bytes', 'r*']!, ['_len', 'Q']!, ['_helper', '@"_NSKeyedUnarchiverHelper"']!, ['_offsetObjMap', '^{__CFDictionary=}']!, ['_pac_signature', 'Q']!]! {
			ivar := objc_find_ivar(cls, pair[0].str)
			assert ivar != 0 && objc_ivar_offset(ivar) == u64(8 + i * 8) && ctext(u64(objc_ivar_types(ivar))) == pair[1]
		}
		for name, expected in {'unarchiveObjectWithData:': '@24@0:8@16', 'unarchiveTopLevelObjectWithData:error:': '@32@0:8@16^@24', 'unarchivedObjectOfClass:fromData:error:': '@40@0:8#16@24^@32', 'unarchivedObjectOfClasses:fromData:error:': '@40@0:8@16@24^@32'} {
			assert objc_responds(cls, name.str)
			assert !objc_responds(api.cls('NSCoder'), name.str)
			assert ctext(u64(objc_method_types(objc_instance_method(read64(cls), u64(name.str))))) == expected
		}
		for selector in [c'alloc', c'new', c'initForReadingWithData:', c'decodeObjectForKey:', c'finishDecoding', c'unarchiveObjectWithFile:', c'delegate', c'setClass:forClassName:']! { assert !objc_responds(cls, selector) }
		// A failed first NSNull constructor must leave no framework-owned sentinel.
		assert objc_add_method(api.cls('NSNull'), u64(c'.cxx_construct'), u64(unsafe { voidptr(keyed_unarchiver_null_constructor) }), c'@16@0:8')
		first_pool := api.pool(); keyed_unarchiver_null_fail = true; mut first_error := u64(0)
		assert api.decode(api.native_data('null'), 2, unsafe { &first_error }) == 0
		keyed_unarchiver_null_fail = false; api.error(first_error, 4864); api.drain(first_pool)
		assert ios_runtime.null_object == 0 && ios_runtime.framework_objects.len == 0 && ios_runtime.live == 0
		// First successful cache publication also runs outside the runtime lock.
		null_pool := api.pool(); keyed_unarchiver_callback_input = objc_allocate(api.cls('NSData'))
		obj_header(keyed_unarchiver_callback_input).data = keyed_unarchive_native_bytes('null')
		keyed_unarchiver_callback_fired = false; mut null_input_weak := u64(0); first_error = 0
		objc_store_weak(unsafe { &null_input_weak }, keyed_unarchiver_callback_input)
		null_result := api.decode(keyed_unarchiver_callback_input, 2, unsafe { &first_error })
		assert keyed_unarchiver_callback_fired && null_input_weak == 0 && first_error == 0
		objc_destroy_weak(unsafe { &null_input_weak }); keyed_unarchiver_callback_input = 0
		api.validate(null_result, 'null'); api.drain(null_pool); keyed_unarchiver_only_cached_null()
		keyed_unarchiver_shared(api); keyed_unarchiver_shared_errors(api); keyed_unarchiver_shared_key_copy(api); keyed_unarchiver_only_cached_null()
		for value in [u64(128), 255, 32768, 65535, 2147483648, 4294967295, 9223372036854775807]! {
			integer_pool := api.pool(); bytes := keyed_unarchive_compact_bytes(value)
			for mode in 0 .. 4 {
				mut integer_error := u64(0)
				number := api.decode(api.data(bytes), mode, unsafe { &integer_error })
				assert integer_error == 0 && api.message(number, c'unsignedIntegerValue', 0, 0, 0, 0) == value
			}
			unsafe { bytes.free() }; api.drain(integer_pool)
		}
		key_pool := api.pool(); key_bytes := keyed_unarchive_extra_graph_bytes('mutable-key'); mut key_error := u64(0)
		key_dict := api.decode(api.data(key_bytes), 3, unsafe { &key_error })
		assert key_error == 0 && api.message(key_dict, c'count', 0, 0, 0, 0) == 1
		assert api.text(api.message(key_dict, c'objectForKey:', api.string('mutable-key'), 0, 0, 0)) == 'value'
		unsafe { key_bytes.free() }; api.drain(key_pool)
		keyed_unarchiver_invalid_archives(api); keyed_unarchiver_only_cached_null()
		pool := api.pool()
		// A constructor may enter the runtime on another thread and retire the input owner.
		input_bytes := keyed_unarchive_native_bytes('string')
		keyed_unarchiver_callback_input = objc_allocate(api.cls('NSData'))
		obj_header(keyed_unarchiver_callback_input).data = input_bytes
		keyed_unarchiver_callback_fired = false; mut input_weak := u64(0)
		objc_store_weak(unsafe { &input_weak }, keyed_unarchiver_callback_input)
		assert objc_add_method(api.cls('NSString'), u64(c'.cxx_construct'), u64(unsafe { voidptr(keyed_unarchiver_string_constructor) }), c'@16@0:8')
		mut error_slot := u64(0)
		result := api.decode(keyed_unarchiver_callback_input, 1, unsafe { &error_slot })
		assert keyed_unarchiver_callback_fired && input_weak == 0 && error_slot == 0
		objc_destroy_weak(unsafe { &input_weak }); keyed_unarchiver_callback_input = 0
		api.validate(result, 'string'); api.drain(pool); keyed_unarchiver_only_cached_null()
		// Failed allocation after the first child must retire every partial graph owner.
		failure_pool := api.pool(); failure_input := api.native_data('array')
		assert objc_add_method(api.cls('NSNumber'), u64(c'.cxx_construct'), u64(unsafe { voidptr(keyed_unarchiver_number_constructor) }), c'@16@0:8')
		keyed_unarchiver_number_fail = true; error_slot = 0
		assert api.decode(failure_input, 2, unsafe { &error_slot }) == 0
		keyed_unarchiver_number_fail = false; api.error(error_slot, 4864)
		api.drain(failure_pool); keyed_unarchiver_only_cached_null()
		objc_stop(); assert ios_runtime.live == 0; system_data_stop()
	}
	println('IOS-KEYED-UNARCHIVER: measured metadata,264 native/Vinix archive cases, independent graph assertions, allowlists/errors, malformed bounds, constructor input pin, partial allocation cleanup and two drained runtimes')
}

fn keyed_unarchiver_read_be(bytes []u8, position int, width int) u64 {
	mut result := u64(0)
	for i in 0 .. width { result = (result << 8) | bytes[position + i] }
	return result
}
fn keyed_unarchiver_write_be(mut bytes []u8, position int, width int, value u64) {
	for i in 0 .. width { bytes[position + i] = u8(value >> u32((width - i - 1) * 8)) }
}
fn keyed_unarchiver_invalid_archives(api KeyedUnarchiveApi) {
	// Native-made schema mutations are independent of Vinix's parser and writer.
	custom := objc_allocate_class(api.cls('NSObject'), c'wrong', 0)
	assert objc_add_method(custom, u64(c'initWithCoder:'), u64(unsafe { voidptr(keyed_unarchiver_forbidden_coding) }), c'@24@0:8@16'); objc_register_class(custom)
	for name in ['root-outside', 'class-name', 'root-missing', 'root-number', 'array-values', 'date-value', 'version', 'objects-empty']! {
		pool := api.pool(); bytes := keyed_unarchive_negative_bytes(name); mut error_slot := u64(0)
		assert api.decode(api.data(bytes), 3, unsafe { &error_slot }) == 0
		api.error(error_slot, if name in ['root-missing', 'root-number']! { 4865 } else { 4864 })
		unsafe { bytes.free() }; api.drain(pool)
	}
	for mode in ['header', 'offset-zero', 'offset-three', 'offset-wide', 'ref-zero', 'ref-three', 'ref-wide', 'empty-table', 'large-count', 'bad-top', 'table-before', 'table-after', 'offset-before', 'offset-after', 'marker', 'uid-width', 'length-width', 'bad-utf16']! {
		pool := api.pool(); mut bytes := keyed_unarchive_native_bytes('string')
		trailer := bytes.len - 32; width := int(bytes[trailer + 6]); table := int(keyed_unarchiver_read_be(bytes, trailer + 24, 8))
		first := int(keyed_unarchiver_read_be(bytes, table, width))
		match mode {
			'header' { bytes[0] = 0 }
			'offset-zero', 'offset-three', 'offset-wide' { bytes[trailer + 6] = if mode == 'offset-zero' { 0 } else if mode == 'offset-three' { 3 } else { 16 } }
			'ref-zero', 'ref-three', 'ref-wide' { bytes[trailer + 7] = if mode == 'ref-zero' { 0 } else if mode == 'ref-three' { 3 } else { 16 } }
			'empty-table' { keyed_unarchiver_write_be(mut bytes, trailer + 8, 8, 0) }
			'large-count' { keyed_unarchiver_write_be(mut bytes, trailer + 8, 8, 65537) }
			'bad-top' { keyed_unarchiver_write_be(mut bytes, trailer + 16, 8, keyed_unarchiver_read_be(bytes, trailer + 8, 8)) }
			'table-before', 'table-after' { keyed_unarchiver_write_be(mut bytes, trailer + 24, 8, if mode == 'table-before' { u64(7) } else { u64(trailer + 1) }) }
			'offset-before', 'offset-after' { keyed_unarchiver_write_be(mut bytes, table, width, if mode == 'offset-before' { u64(7) } else { u64(table) }) }
			'marker' { bytes[first] = 0 }
			'uid-width' { bytes[first] = 0x88 }
			'length-width' { bytes[first] = 0x5f; bytes[first + 1] = 0x1f }
			else { bytes[first] = 0x61; bytes[first + 1] = 0xd8; bytes[first + 2] = 0 }
		}
		mut error_slot := u64(0); assert api.decode(api.data(bytes), 2, unsafe { &error_slot }) == 0; api.error(error_slot, 4864)
		unsafe { bytes.free() }; api.drain(pool)
	}
	for mode in ['cycle', 'bad-uid']! {
		pool := api.pool(); mut bytes := keyed_unarchive_native_bytes('array')
		trailer := bytes.len - 32; offset_width := int(bytes[trailer + 6]); ref_width := int(bytes[trailer + 7])
		count := int(keyed_unarchiver_read_be(bytes, trailer + 8, 8)); table := int(keyed_unarchiver_read_be(bytes, trailer + 24, 8))
		mut target := 0
		// Follow plist references to the independently captured array's UID nodes.
		// The four array references are not inline UID records.
		for i in 0 .. count {
			at := int(keyed_unarchiver_read_be(bytes, table + i * offset_width, offset_width))
			if bytes[at] != 0xa4 { continue }
			mut matches := true; mut first_payload := 0
			for j, expected in [u8(2), 3, 2, 4]! {
				reference := int(keyed_unarchiver_read_be(bytes, at + 1 + j * ref_width, ref_width))
				uid_at := int(keyed_unarchiver_read_be(bytes, table + reference * offset_width, offset_width))
				if bytes[uid_at] != 0x80 || bytes[uid_at + 1] != expected { matches = false; break }
				if j == 0 { first_payload = uid_at + 1 }
			}
			if matches { assert target == 0; target = first_payload }
		}
		assert target != 0
		bytes[target] = if mode == 'cycle' { 1 } else { 255 }
		mut error_slot := u64(0); assert api.decode(api.data(bytes), 2, unsafe { &error_slot }) == 0; api.error(error_slot, 4864)
		unsafe { bytes.free() }; api.drain(pool)
	}
	pool := api.pool(); bytes := keyed_unarchive_depth65_bytes(); mut error_slot := u64(0)
	assert api.decode(api.data(bytes), 2, unsafe { &error_slot }) == 0; api.error(error_slot, 4864)
	unsafe { bytes.free() }; api.drain(pool)
	alias_pool := api.pool(); alias_bytes := keyed_unarchive_extra_graph_bytes('cached-depth'); error_slot = 0
	assert api.decode(api.data(alias_bytes), 2, unsafe { &error_slot }) == 0; api.error(error_slot, 4864)
	unsafe { alias_bytes.free() }; api.drain(alias_pool)
}

fn test_keyed_unarchiver_rejections() {
	objc_start(); system_data_start()!; api := keyed_unarchiver_runtime_api()
	modes := ['alloc', 'allocWithZone:', 'new', 'init', 'initForReadingWithData:', 'initForReadingFromData:error:', 'decodeObjectForKey:', 'decodeObjectOfClass:forKey:', 'decodeObjectOfClasses:forKey:', 'finishDecoding', 'requiresSecureCoding', 'setRequiresSecureCoding:', 'decodingFailurePolicy', 'setDecodingFailurePolicy:', 'delegate', 'setDelegate:', 'error', 'allowsKeyedCoding', 'unarchiveObjectWithFile:', 'classForClassName:', 'setClass:forClassName:', 'copy', 'mutableCopy', 'supportsSecureCoding', 'caller-storage', 'custom-factory', 'input-object', 'input-class', 'input-custom', 'input-spoof', 'input-isa', 'allow-object', 'allow-class', 'allow-custom', 'allow-spoof', 'allow-raw', 'allow-member', 'nil-class', 'size']!
	for mode in modes {
		mut fds := [2]i32{}; assert C.pipe(unsafe { &fds[0] }) == 0
		pid := C.ios_fork(); assert pid >= 0
		if pid == 0 {
			C.close(fds[0]); assert C.dup2(fds[1], 2) == 2; C.close(fds[1])
			pool := api.pool(); mut input := api.native_data('string'); mut allowed := api.allowed(['NSObject'])
			match mode {
				'caller-storage' { mut storage := [18]u64{}; objc_construct_instance(api.cls('NSKeyedUnarchiver'), u64(unsafe { &storage[0] })) }
				'custom-factory' { cls := objc_allocate_class(api.cls('NSKeyedUnarchiver'), c'VinixUnsupportedUnarchiver', 0); objc_register_class(cls); api.message(cls, c'unarchiveObjectWithData:', input, 0, 0, 0) }
				'input-object' { input = objc_new(api.cls('NSObject')) }
				'input-class' { input = api.cls('NSData') }
				'input-custom' { cls := objc_allocate_class(api.cls('NSData'), c'VinixUnsupportedDecodeData', 0); objc_register_class(cls); input = objc_new(cls) }
